   "code": "// Ticketing: atomic conditional holds mean no seat is ever sold twice\nconst seats = new Map();                                   // seatId -> { holder, expires }\nfunction tryHold(seat, user, now, ttl = 600) {             // like: UPDATE ... WHERE holder IS NULL OR expires < now\n  const s = seats.get(seat);\n  if (s && s.expires > now) return false;\n  seats.set(seat, { holder: user, expires: now + ttl });\n  return true;\n}\nlet x = 7; const rand = n => (x = (x * 1103515245 + 12345) % 2 ** 31, (x >>> 15) % n);   // repeatable\nlet granted = 0, rejected = 0;\nfor (let u = 0; u < 5000; u++) tryHold(rand(200), u, 0) ? granted++ : rejected++;\nconst holders = [...seats.values()].map(s => s.holder);\nconsole.log(`5000 buyers, 200 seats: granted ${granted}, rejected ${rejected}, seats held twice: ${holders.length - new Set(holders).size === 0 && granted === seats.size ? 0 : 'BUG'}`);\n\n// Payments: double-entry ledger, every transfer sums to zero\nconst ledger = [];\nfunction transfer(id, from, to, cents) {\n  if (ledger.some(e => e.id === id)) return 'duplicate ignored';   // idempotency key\n  ledger.push({ id, account: from, cents: -cents }, { id, account: to, cents });\n  return 'ok';\n}\nconsole.log(transfer('t1', 'alice', 'bob', 2500), transfer('t1', 'alice', 'bob', 2500), transfer('t2', 'bob', 'shop', 1000));\nconst balance = a => ledger.filter(e => e.account === a).reduce((s, e) => s + e.cents, 0);\nconsole.log('alice', balance('alice'), 'bob', balance('bob'), 'shop', balance('shop'), 'total', ledger.reduce((s, e) => s + e.cents, 0));",
